CREATE TRIGGER target_approval_overlap BEFORE UPDATE OF status ON target_version WHEN NEW.status='approved' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM target_version v JOIN target_plan p ON p.id=v.target_plan_id AND p.organization_id=v.organization_id JOIN target_plan n ON n.id=NEW.target_plan_id AND n.organization_id=NEW.organization_id WHERE v.organization_id=NEW.organization_id AND v.status='approved' AND v.target_plan_id<>NEW.target_plan_id AND p.channel=n.channel AND p.period_start<=n.period_end AND p.period_end>=n.period_start) THEN RAISE(ABORT,'OVERLAPPING_APPROVED_PLAN') END;
END;
CREATE TRIGGER target_version_values_locked BEFORE UPDATE ON target_version WHEN OLD.status IN('approved','superseded') AND (NEW.parent_minor<>OLD.parent_minor OR NEW.reserve_minor<>OLD.reserve_minor OR NEW.target_plan_id<>OLD.target_plan_id OR NEW.revision_no<>OLD.revision_no OR NEW.organization_id<>OLD.organization_id OR NEW.created_by<>OLD.created_by OR NEW.baseline_json IS NOT OLD.baseline_json OR NEW.status NOT IN('approved','superseded')) BEGIN SELECT RAISE(ABORT,'TARGET_LOCKED');END;
CREATE TRIGGER segmentation_snapshot_immutable_update BEFORE UPDATE ON customer_status_snapshot BEGIN SELECT RAISE(ABORT,'SNAPSHOT_IMMUTABLE');END;
CREATE TRIGGER segmentation_snapshot_immutable_delete BEFORE DELETE ON customer_status_snapshot BEGIN SELECT RAISE(ABORT,'SNAPSHOT_IMMUTABLE');END;
